on call close() -> Effect[()] {
  self.erase()
  closed := true    // ✗ the commit deletes the instance, so nothing is written
}

on call close() -> Effect[()] given Events {
  do Events.emit[AccountClosed](AccountClosed { id: self.id })
  self.erase()    // ✓ the event records it; the state goes
}
